-- PARTE 1 — Vocabulário (30 palavras, cefr_level = 'C1')
-- ============================================================
insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002251', 'this essay will argue that', '/ðɪs ˈeseɪ wɪl ˈɑːrɡjuː ðæt/', 'phrase', 'esta redação vai defender que', 'This essay will argue that remote work increases long-term productivity.', 'Esta redação vai defender que o trabalho remoto aumenta a produtividade a longo prazo.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002252', 'it is widely believed that', '/ɪt ɪz ˈwaɪdli bɪˈliːvd ðæt/', 'phrase', 'acredita-se amplamente que', 'It is widely believed that technology has changed education forever.', 'Acredita-se amplamente que a tecnologia mudou a educação para sempre.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002253', 'the purpose of this essay is to', '/ðə ˈpɜːrpəs əv ðɪs ˈeseɪ ɪz tuː/', 'phrase', 'o objetivo desta redação é', 'The purpose of this essay is to examine the effects of social media on teenagers.', 'O objetivo desta redação é examinar os efeitos das redes sociais em adolescentes.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002254', 'this essay examines', '/ðɪs ˈeseɪ ɪɡˈzæmɪnz/', 'phrase', 'esta redação examina', 'This essay examines the advantages and disadvantages of remote learning.', 'Esta redação examina as vantagens e desvantagens do aprendizado remoto.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002255', 'at first glance', '/æt fɜːrst ɡlæns/', 'phrase', 'à primeira vista', 'At first glance, the solution seems simple, but it is not.', 'À primeira vista, a solução parece simples, mas não é.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002256', 'a case in point', '/ə keɪs ɪn pɔɪnt/', 'phrase', 'um exemplo claro disso', 'The recent merger is a case in point.', 'A fusão recente é um exemplo claro disso.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002257', 'on the one hand... on the other hand', '/ɒn ðə wʌn hænd ɒn ði ˈʌðər hænd/', 'phrase', 'por um lado... por outro lado', 'On the one hand, remote work saves time; on the other hand, it can be isolating.', 'Por um lado, o trabalho remoto economiza tempo; por outro lado, pode ser isolante.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002258', 'whereas', '/werˈæz/', 'conjunction', 'enquanto que', 'Sales increased in the first quarter, whereas costs remained stable.', 'As vendas aumentaram no primeiro trimestre, enquanto os custos permaneceram estáveis.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002259', 'conversely', '/kənˈvɜːrsli/', 'adverb', 'inversamente', 'Conversely, smaller companies often adapt faster to change.', 'Inversamente, empresas menores costumam se adaptar mais rápido a mudanças.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002260', 'critics argue that', '/ˈkrɪtɪks ˈɑːrɡjuː ðæt/', 'phrase', 'críticos argumentam que', 'Critics argue that the policy favors large corporations.', 'Críticos argumentam que a política favorece grandes corporações.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002261', 'opponents of this view claim', '/əˈpoʊnənts əv ðɪs vjuː kleɪm/', 'phrase', 'opositores dessa visão afirmam', 'Opponents of this view claim that the risks outweigh the benefits.', 'Opositores dessa visão afirmam que os riscos superam os benefícios.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002262', 'proponents of this view argue', '/prəˈpoʊnənts əv ðɪs vjuː ˈɑːrɡjuː/', 'phrase', 'defensores dessa visão argumentam', 'Proponents of this view argue that automation creates new jobs.', 'Defensores dessa visão argumentam que a automação cria novos empregos.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002263', 'in addition to this', '/ɪn əˈdɪʃən tuː ðɪs/', 'phrase', 'além disso', 'In addition to this, the new system reduces errors.', 'Além disso, o novo sistema reduz erros.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002264', 'what is more', '/wʌt ɪz mɔːr/', 'phrase', 'além do mais', 'What is more, the change was implemented at no extra cost.', 'Além do mais, a mudança foi implementada sem custo adicional.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002265', 'equally important', '/ˈiːkwəli ɪmˈpɔːrtənt/', 'phrase', 'igualmente importante', 'Equally important is the impact of the decision on staff morale.', 'Igualmente importante é o impacto da decisão no ânimo da equipe.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002266', 'similarly', '/ˈsɪmɪlərli/', 'adverb', 'da mesma forma', 'Similarly, other departments reported an increase in efficiency.', 'Da mesma forma, outros departamentos relataram um aumento na eficiência.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002267', 'likewise', '/ˈlaɪkwaɪz/', 'adverb', 'da mesma forma', 'Likewise, customer feedback has been overwhelmingly positive.', 'Da mesma forma, o feedback dos clientes tem sido extremamente positivo.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002268', 'by the same token', '/baɪ ðə seɪm ˈtoʊkən/', 'phrase', 'pela mesma lógica', 'By the same token, reducing costs should not compromise quality.', 'Pela mesma lógica, reduzir custos não deveria comprometer a qualidade.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002269', 'this leads to', '/ðɪs liːdz tuː/', 'phrase', 'isso leva a', 'This leads to a significant increase in customer trust.', 'Isso leva a um aumento significativo na confiança do cliente.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002270', 'as a consequence', '/æz ə ˈkɒnsɪkwəns/', 'phrase', 'como consequência', 'As a consequence, the company had to revise its entire strategy.', 'Como consequência, a empresa teve que revisar toda a sua estratégia.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002271', 'this in turn', '/ðɪs ɪn tɜːrn/', 'phrase', 'isso, por sua vez', 'Sales grew, and this in turn allowed for further investment.', 'As vendas cresceram, e isso, por sua vez, permitiu mais investimento.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002272', 'thereby', '/ðerˈbaɪ/', 'adverb', 'assim, dessa forma', 'The company automated the process, thereby reducing costs.', 'A empresa automatizou o processo, reduzindo os custos dessa forma.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002273', 'which means that', '/wɪtʃ miːnz ðæt/', 'phrase', 'o que significa que', 'Demand has doubled, which means that production must increase.', 'A demanda dobrou, o que significa que a produção precisa aumentar.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002274', 'hence', '/hens/', 'adverb', 'portanto', 'The results were inconclusive; hence, further research is needed.', 'Os resultados foram inconclusivos; portanto, mais pesquisa é necessária.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002275', 'to conclude', '/tuː kənˈkluːd/', 'phrase', 'para concluir', 'To conclude, the evidence strongly supports this approach.', 'Para concluir, as evidências apoiam fortemente essa abordagem.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002276', 'in summary', '/ɪn ˈsʌməri/', 'phrase', 'em resumo', 'In summary, the project achieved most of its original goals.', 'Em resumo, o projeto atingiu a maioria de seus objetivos originais.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002277', 'taking all of this into consideration', '/ˈteɪkɪŋ ɔːl əv ðɪs ˈɪntuː kənˌsɪdəˈreɪʃən/', 'phrase', 'levando tudo isso em consideração', 'Taking all of this into consideration, the committee approved the proposal.', 'Levando tudo isso em consideração, o comitê aprovou a proposta.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002278', 'it can be concluded that', '/ɪt kæn biː kənˈkluːdɪd ðæt/', 'phrase', 'pode-se concluir que', 'It can be concluded that further investment is necessary.', 'Pode-se concluir que mais investimento é necessário.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002279', 'all in all', '/ɔːl ɪn ɔːl/', 'phrase', 'no geral', 'All in all, the strategy proved successful.', 'No geral, a estratégia se mostrou bem-sucedida.', 'C1', array['essay-writing']),
('30000000-0000-0000-0000-000000002280', 'in the final analysis', '/ɪn ðə ˈfaɪnəl əˈnæləsɪs/', 'phrase', 'em última análise', 'In the final analysis, the benefits outweigh the costs.', 'Em última análise, os benefícios superam os custos.', 'C1', array['essay-writing']);

