-- Lição 376: Introdução de redação argumentativa (this essay will argue that, it is widely believed that, the purpose of this essay is to, this essay examines, at first glance, a case in point)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000376', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002251", "show_image": false}'),
('20000000-0000-0000-0000-000000000376', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002253", "show_image": false}'),
('20000000-0000-0000-0000-000000000376', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002256", "show_image": false}'),
('20000000-0000-0000-0000-000000000376', 'multiple_choice', 4, '{"question": "___ remote work increases long-term productivity.", "audio_text": null, "options": ["This essay will argue that", "In summary", "Whereas"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000376', 'multiple_choice', 5, '{"question": "___, the solution seems simple, but it is not.", "audio_text": null, "options": ["At first glance", "Hence", "Thereby"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000376', 'matching', 6, '{"pairs": [{"left": "this essay will argue that", "right": "esta redação vai defender que"}, {"left": "it is widely believed that", "right": "acredita-se amplamente que"}, {"left": "the purpose of this essay is to", "right": "o objetivo desta redação é"}, {"left": "this essay examines", "right": "esta redação examina"}, {"left": "at first glance", "right": "à primeira vista"}, {"left": "a case in point", "right": "um exemplo claro disso"}]}'),
('20000000-0000-0000-0000-000000000376', 'fill_blank', 7, '{"sentence": "___ technology has changed education forever.", "options": ["It is widely believed that", "This in turn", "By the same token"], "correct": "It is widely believed that", "translation": "Acredita-se amplamente que a tecnologia mudou a educação para sempre."}'),
('20000000-0000-0000-0000-000000000376', 'fill_blank', 8, '{"sentence": "The recent merger is ___.", "options": ["a case in point", "at first glance", "in summary"], "correct": "a case in point", "translation": "A fusão recente é um exemplo claro disso."}'),
('20000000-0000-0000-0000-000000000376', 'word_order', 9, '{"words": ["The", "purpose", "of", "this", "essay", "is", "to", "examine", "the", "effects", "of", "social", "media", "on", "teenagers"], "correct_sentence": "The purpose of this essay is to examine the effects of social media on teenagers", "translation": "O objetivo desta redação é examinar os efeitos das redes sociais em adolescentes"}'),
('20000000-0000-0000-0000-000000000376', 'word_order', 10, '{"words": ["This", "essay", "examines", "the", "advantages", "and", "disadvantages", "of", "remote", "learning"], "correct_sentence": "This essay examines the advantages and disadvantages of remote learning", "translation": "Esta redação examina as vantagens e desvantagens do aprendizado remoto"}'),
('20000000-0000-0000-0000-000000000376', 'reading', 11, '{"passage": "Formal essays usually open with a clear statement of purpose. Phrases like ''this essay will argue that'', ''the purpose of this essay is to'' and ''this essay examines'' tell the reader exactly what to expect. Writers often add a common belief with ''it is widely believed that'' before challenging or supporting it, and phrases like ''at first glance'' and ''a case in point'' help introduce ideas and examples.", "translation": "Redações formais geralmente começam com uma declaração clara de propósito. Frases como ''this essay will argue that'', ''the purpose of this essay is to'' e ''this essay examines'' dizem ao leitor exatamente o que esperar. Autores costumam acrescentar uma crença comum com ''it is widely believed that'' antes de questioná-la ou apoiá-la, e frases como ''at first glance'' e ''a case in point'' ajudam a introduzir ideias e exemplos.", "question": "What do phrases like ''this essay will argue that'' tell the reader, according to the text?", "options": ["Exactly what to expect", "The essay is finished", "A joke is coming"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000376', 'listening', 12, '{"audio_text": "This essay will argue that remote work increases long-term productivity. It is widely believed that technology has changed education forever. At first glance, the solution seems simple, but it is not.", "question": "What does this essay argue, according to the audio?", "options": ["That remote work increases long-term productivity", "That technology is unreliable", "That the solution is complex"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000376', 'dictation', 13, '{"audio_text": "This essay will argue that remote work increases long-term productivity.", "expected": "This essay will argue that remote work increases long-term productivity."}'),
('20000000-0000-0000-0000-000000000376', 'typing', 14, '{"prompt_pt": "Traduza: ''O objetivo desta redação é examinar por que, à primeira vista, essa política parece eficaz.''", "expected": "The purpose of this essay is to examine why, at first glance, this policy seems effective.", "ai_review": true}'),

-- Lição 377: Contraste e contra-argumento (on the one hand... on the other hand, whereas, conversely, critics argue that, opponents of this view claim, proponents of this view argue)
('20000000-0000-0000-0000-000000000377', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002257", "show_image": false}'),
('20000000-0000-0000-0000-000000000377', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002260", "show_image": false}'),
('20000000-0000-0000-0000-000000000377', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002262", "show_image": false}'),
('20000000-0000-0000-0000-000000000377', 'multiple_choice', 4, '{"question": "Sales increased in the first quarter, ___ costs remained stable.", "audio_text": null, "options": ["whereas", "hence", "similarly"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000377', 'multiple_choice', 5, '{"question": "___ that the policy favors large corporations.", "audio_text": null, "options": ["Critics argue", "This leads to", "In summary"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000377', 'matching', 6, '{"pairs": [{"left": "on the one hand... on the other hand", "right": "por um lado... por outro lado"}, {"left": "whereas", "right": "enquanto que"}, {"left": "conversely", "right": "inversamente"}, {"left": "critics argue that", "right": "críticos argumentam que"}, {"left": "opponents of this view claim", "right": "opositores dessa visão afirmam"}, {"left": "proponents of this view argue", "right": "defensores dessa visão argumentam"}]}'),
('20000000-0000-0000-0000-000000000377', 'fill_blank', 7, '{"sentence": "___, smaller companies often adapt faster to change.", "options": ["Conversely", "Whereas", "This leads to"], "correct": "Conversely", "translation": "Inversamente, empresas menores costumam se adaptar mais rápido a mudanças."}'),
('20000000-0000-0000-0000-000000000377', 'fill_blank', 8, '{"sentence": "___ that automation creates new jobs.", "options": ["Proponents of this view argue", "As a consequence", "In the final analysis"], "correct": "Proponents of this view argue", "translation": "Defensores dessa visão argumentam que a automação cria novos empregos."}'),
('20000000-0000-0000-0000-000000000377', 'word_order', 9, '{"words": ["On", "the", "one", "hand", "remote", "work", "saves", "time", "on", "the", "other", "hand", "it", "can", "be", "isolating"], "correct_sentence": "On the one hand remote work saves time on the other hand it can be isolating", "translation": "Por um lado, o trabalho remoto economiza tempo; por outro lado, pode ser isolante"}'),
('20000000-0000-0000-0000-000000000377', 'word_order', 10, '{"words": ["Opponents", "of", "this", "view", "claim", "that", "the", "risks", "outweigh", "the", "benefits"], "correct_sentence": "Opponents of this view claim that the risks outweigh the benefits", "translation": "Opositores dessa visão afirmam que os riscos superam os benefícios"}'),
('20000000-0000-0000-0000-000000000377', 'reading', 11, '{"passage": "A strong essay presents both sides of an argument before taking a position. ''On the one hand... on the other hand'' and ''whereas'' introduce a direct contrast, while ''conversely'' signals an opposite point. Phrases like ''critics argue that'', ''opponents of this view claim'' and ''proponents of this view argue'' let the writer present different perspectives fairly before responding to them.", "translation": "Uma boa redação apresenta os dois lados de um argumento antes de tomar uma posição. ''On the one hand... on the other hand'' e ''whereas'' introduzem um contraste direto, enquanto ''conversely'' sinaliza um ponto oposto. Frases como ''critics argue that'', ''opponents of this view claim'' e ''proponents of this view argue'' permitem que o autor apresente diferentes perspectivas de forma justa antes de responder a elas.", "question": "What does a strong essay do before taking a position, according to the text?", "options": ["Presents both sides of an argument", "Ignores the opposing view", "Ends the discussion immediately"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000377', 'listening', 12, '{"audio_text": "Sales increased in the first quarter, whereas costs remained stable. Critics argue that the policy favors large corporations. Proponents of this view argue that automation creates new jobs.", "question": "What remained stable, according to the audio?", "options": ["Costs", "Sales", "Jobs"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000377', 'dictation', 13, '{"audio_text": "Critics argue that the policy favors large corporations.", "expected": "Critics argue that the policy favors large corporations."}'),
('20000000-0000-0000-0000-000000000377', 'typing', 14, '{"prompt_pt": "Traduza: ''Por um lado, críticos argumentam que o risco é alto; por outro lado, defensores dessa visão argumentam que o benefício é maior.''", "expected": "On the one hand, critics argue that the risk is high; on the other hand, proponents of this view argue that the benefit is greater.", "ai_review": true}'),

-- Lição 378: Adição de ideias e ênfase (in addition to this, what is more, equally important, similarly, likewise, by the same token)
('20000000-0000-0000-0000-000000000378', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002263", "show_image": false}'),
('20000000-0000-0000-0000-000000000378', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002265", "show_image": false}'),
('20000000-0000-0000-0000-000000000378', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002267", "show_image": false}'),
('20000000-0000-0000-0000-000000000378', 'multiple_choice', 4, '{"question": "___, the new system reduces errors.", "audio_text": null, "options": ["In addition to this", "Whereas", "In the final analysis"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000378', 'multiple_choice', 5, '{"question": "___, customer feedback has been overwhelmingly positive.", "audio_text": null, "options": ["Likewise", "Hence", "Conversely"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000378', 'matching', 6, '{"pairs": [{"left": "in addition to this", "right": "além disso"}, {"left": "what is more", "right": "além do mais"}, {"left": "equally important", "right": "igualmente importante"}, {"left": "similarly", "right": "da mesma forma"}, {"left": "likewise", "right": "da mesma forma"}, {"left": "by the same token", "right": "pela mesma lógica"}]}'),
('20000000-0000-0000-0000-000000000378', 'fill_blank', 7, '{"sentence": "___ is the impact of the decision on staff morale.", "options": ["Equally important", "This leads to", "In summary"], "correct": "Equally important", "translation": "Igualmente importante é o impacto da decisão no ânimo da equipe."}'),
('20000000-0000-0000-0000-000000000378', 'fill_blank', 8, '{"sentence": "___, reducing costs should not compromise quality.", "options": ["By the same token", "As a consequence", "To conclude"], "correct": "By the same token", "translation": "Pela mesma lógica, reduzir custos não deveria comprometer a qualidade."}'),
('20000000-0000-0000-0000-000000000378', 'word_order', 9, '{"words": ["What", "is", "more", "the", "change", "was", "implemented", "at", "no", "extra", "cost"], "correct_sentence": "What is more the change was implemented at no extra cost", "translation": "Além do mais, a mudança foi implementada sem custo adicional"}'),
('20000000-0000-0000-0000-000000000378', 'word_order', 10, '{"words": ["Similarly", "other", "departments", "reported", "an", "increase", "in", "efficiency"], "correct_sentence": "Similarly other departments reported an increase in efficiency", "translation": "Da mesma forma, outros departamentos relataram um aumento na eficiência"}'),
('20000000-0000-0000-0000-000000000378', 'reading', 11, '{"passage": "Good essays add supporting ideas smoothly instead of listing them abruptly. ''In addition to this'' and ''what is more'' introduce an extra point, while ''equally important'' signals that the next idea matters just as much as the last one. ''Similarly'' and ''likewise'' connect comparable examples, and ''by the same token'' applies the same logic to a new situation.", "translation": "Boas redações acrescentam ideias de apoio de forma fluida, em vez de listá-las abruptamente. ''In addition to this'' e ''what is more'' introduzem um ponto extra, enquanto ''equally important'' sinaliza que a próxima ideia importa tanto quanto a anterior. ''Similarly'' e ''likewise'' conectam exemplos comparáveis, e ''by the same token'' aplica a mesma lógica a uma nova situação.", "question": "What does ''equally important'' signal, according to the text?", "options": ["That the next idea matters just as much as the last one", "That the essay is ending", "That the writer disagrees"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000378', 'listening', 12, '{"audio_text": "In addition to this, the new system reduces errors. Equally important is the impact of the decision on staff morale. Similarly, other departments reported an increase in efficiency.", "question": "What does the new system do, according to the audio?", "options": ["Reduces errors", "Increases costs", "Lowers morale"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000378', 'dictation', 13, '{"audio_text": "In addition to this, the new system reduces errors.", "expected": "In addition to this, the new system reduces errors."}'),
('20000000-0000-0000-0000-000000000378', 'typing', 14, '{"prompt_pt": "Traduza: ''Além disso, os custos caíram; da mesma forma, a satisfação do cliente aumentou.''", "expected": "In addition to this, costs fell; likewise, customer satisfaction increased.", "ai_review": true}'),

