('20000000-0000-0000-0000-000000000379', 'multiple_choice', 4, '{"question": "The company automated the process, ___ reducing costs.", "audio_text": null, "options": ["thereby", "whereas", "similarly"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000379', 'multiple_choice', 5, '{"question": "The results were inconclusive; ___, further research is needed.", "audio_text": null, "options": ["hence", "likewise", "conversely"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000379', 'matching', 6, '{"pairs": [{"left": "this leads to", "right": "isso leva a"}, {"left": "as a consequence", "right": "como consequência"}, {"left": "this in turn", "right": "isso, por sua vez"}, {"left": "thereby", "right": "assim, dessa forma"}, {"left": "which means that", "right": "o que significa que"}, {"left": "hence", "right": "portanto"}]}'),
('20000000-0000-0000-0000-000000000379', 'fill_blank', 7, '{"sentence": "___, the company had to revise its entire strategy.", "options": ["As a consequence", "Similarly", "In addition to this"], "correct": "As a consequence", "translation": "Como consequência, a empresa teve que revisar toda a sua estratégia."}'),
('20000000-0000-0000-0000-000000000379', 'fill_blank', 8, '{"sentence": "Demand has doubled, ___ production must increase.", "options": ["which means that", "whereas", "by the same token"], "correct": "which means that", "translation": "A demanda dobrou, o que significa que a produção precisa aumentar."}'),
('20000000-0000-0000-0000-000000000379', 'word_order', 9, '{"words": ["Sales", "grew", "and", "this", "in", "turn", "allowed", "for", "further", "investment"], "correct_sentence": "Sales grew and this in turn allowed for further investment", "translation": "As vendas cresceram, e isso, por sua vez, permitiu mais investimento"}'),
('20000000-0000-0000-0000-000000000379', 'word_order', 10, '{"words": ["This", "leads", "to", "a", "significant", "increase", "in", "customer", "trust"], "correct_sentence": "This leads to a significant increase in customer trust", "translation": "Isso leva a um aumento significativo na confiança do cliente"}'),
('20000000-0000-0000-0000-000000000379', 'reading', 11, '{"passage": "Cause-and-effect connectors help essays explain why one event produces another. ''This leads to'' and ''as a consequence'' introduce a direct result, while ''this in turn'' shows a chain of effects. ''Thereby'' links an action to its outcome within the same sentence, and ''which means that'' and ''hence'' draw a logical conclusion from what came before.", "translation": "Conectores de causa e efeito ajudam redações a explicar por que um evento produz outro. ''This leads to'' e ''as a consequence'' introduzem um resultado direto, enquanto ''this in turn'' mostra uma cadeia de efeitos. ''Thereby'' conecta uma ação ao seu resultado dentro da mesma frase, e ''which means that'' e ''hence'' tiram uma conclusão lógica do que veio antes.", "question": "What does ''this in turn'' show, according to the text?", "options": ["A chain of effects", "A direct contrast", "An unrelated example"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000379', 'listening', 12, '{"audio_text": "The company automated the process, thereby reducing costs. Demand has doubled, which means that production must increase. The results were inconclusive; hence, further research is needed.", "question": "What did the company do to reduce costs, according to the audio?", "options": ["Automated the process", "Increased demand", "Stopped research"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000379', 'dictation', 13, '{"audio_text": "The company automated the process, thereby reducing costs.", "expected": "The company automated the process, thereby reducing costs."}'),
('20000000-0000-0000-0000-000000000379', 'typing', 14, '{"prompt_pt": "Traduza: ''A demanda aumentou, o que significa que precisamos contratar mais pessoas; como consequência, os custos vão subir.''", "expected": "Demand has increased, which means that we need to hire more people; as a consequence, costs will rise.", "ai_review": true}'),

-- Lição 380: Revisão final: conclusão de redação (to conclude, in summary, taking all of this into consideration, it can be concluded that, all in all, in the final analysis)
('20000000-0000-0000-0000-000000000380', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002275", "show_image": false}'),
('20000000-0000-0000-0000-000000000380', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002278", "show_image": false}'),
('20000000-0000-0000-0000-000000000380', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002280", "show_image": false}'),
('20000000-0000-0000-0000-000000000380', 'multiple_choice', 4, '{"question": "___, the evidence strongly supports this approach.", "audio_text": null, "options": ["To conclude", "Whereas", "This leads to"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000380', 'multiple_choice', 5, '{"question": "___, the strategy proved successful.", "audio_text": null, "options": ["All in all", "Conversely", "Critics argue that"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000380', 'matching', 6, '{"pairs": [{"left": "to conclude", "right": "para concluir"}, {"left": "in summary", "right": "em resumo"}, {"left": "taking all of this into consideration", "right": "levando tudo isso em consideração"}, {"left": "it can be concluded that", "right": "pode-se concluir que"}, {"left": "all in all", "right": "no geral"}, {"left": "in the final analysis", "right": "em última análise"}]}'),
('20000000-0000-0000-0000-000000000380', 'fill_blank', 7, '{"sentence": "___, the project achieved most of its original goals.", "options": ["In summary", "Conversely", "Opponents of this view claim"], "correct": "In summary", "translation": "Em resumo, o projeto atingiu a maioria de seus objetivos originais."}'),
('20000000-0000-0000-0000-000000000380', 'fill_blank', 8, '{"sentence": "___, the benefits outweigh the costs.", "options": ["In the final analysis", "Whereas", "This in turn"], "correct": "In the final analysis", "translation": "Em última análise, os benefícios superam os custos."}'),
('20000000-0000-0000-0000-000000000380', 'word_order', 9, '{"words": ["Taking", "all", "of", "this", "into", "consideration", "the", "committee", "approved", "the", "proposal"], "correct_sentence": "Taking all of this into consideration the committee approved the proposal", "translation": "Levando tudo isso em consideração, o comitê aprovou a proposta"}'),
('20000000-0000-0000-0000-000000000380', 'word_order', 10, '{"words": ["It", "can", "be", "concluded", "that", "further", "investment", "is", "necessary"], "correct_sentence": "It can be concluded that further investment is necessary", "translation": "Pode-se concluir que mais investimento é necessário"}'),
('20000000-0000-0000-0000-000000000380', 'reading', 11, '{"passage": "This review brings together the whole cohesion and formal essay writing module. An essay opens with ''this essay will argue that'' or ''the purpose of this essay is to'', develops through contrast (''whereas'', ''conversely''), addition (''in addition to this'', ''similarly'') and cause-effect (''this leads to'', ''hence''), and closes with ''to conclude'', ''in summary'' or ''in the final analysis''. All in all, mastering these connectors, together with the nominalized vocabulary from the previous module, is what makes an essay sound truly C1-level.", "translation": "Esta revisão reúne todo o módulo de coesão e redação formal. Uma redação começa com ''this essay will argue that'' ou ''the purpose of this essay is to'', se desenvolve por meio de contraste (''whereas'', ''conversely''), adição (''in addition to this'', ''similarly'') e causa-efeito (''this leads to'', ''hence''), e termina com ''to conclude'', ''in summary'' ou ''in the final analysis''. No geral, dominar esses conectores, junto com o vocabulário nominalizado do módulo anterior, é o que faz uma redação soar verdadeiramente de nível C1.", "question": "According to the text, what makes an essay sound truly C1-level?", "options": ["Mastering cohesive connectors and nominalized vocabulary", "Using only short sentences", "Avoiding all conclusions"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000380', 'listening', 12, '{"audio_text": "To conclude, the evidence strongly supports this approach. Taking all of this into consideration, the committee approved the proposal. All in all, the strategy proved successful.", "question": "What did the committee do, according to the audio?", "options": ["Approved the proposal", "Rejected the evidence", "Delayed the strategy"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000380', 'dictation', 13, '{"audio_text": "To conclude, the evidence strongly supports this approach.", "expected": "To conclude, the evidence strongly supports this approach."}'),
('20000000-0000-0000-0000-000000000380', 'typing', 14, '{"prompt_pt": "Traduza: ''Em resumo, e levando tudo isso em consideração, pode-se concluir que a proposta merece aprovação.''", "expected": "In summary, and taking all of this into consideration, it can be concluded that the proposal deserves approval.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000380', 'typing', 15, '{"prompt_pt": "Traduza: ''Esta redação vai defender que, em última análise, o trabalho remoto traz mais benefícios do que desvantagens.''", "expected": "This essay will argue that, in the final analysis, remote work brings more benefits than disadvantages.", "ai_review": true}');

